        fcb     $30,$75          ; 30000 cycles (low byte first): 50 Hz
        fcb     $7C,$92          ; 37500 cycles (low byte first): 40 Hz
        fcb     $50,$C3          ; 50000 cycles (low byte first): 30 Hz
        fcb     $60,$EA          ; 60000 cycles (low byte first): 25 Hz
